#include <iostream>
#include <vector>
#include <cmath>
#include <limits>

typedef long long int int64;

inline int64 abs_custom(int64 x) {
    return x < 0 ? -x : x;
}

int main() {
    int64 n;
    int k;  // Using int for better performance
    std::cin >> n >> k;

    std::vector<int64> h(n);
    for (int64 i = 0; i < n; i++)
        std::cin >> h[i];

    std::vector<int64> ans(n, std::numeric_limits<int64>::max());
    ans[0] = 0;  // Base case

    for (int64 i = 1; i < n; i++) {
        ans[i] = abs_custom(h[i] - h[i - 1]) + ans[i - 1];
        for (int64 j = 2; j <= i && j <= k; j++) {
            ans[i] = std::min(ans[i], abs_custom(h[i] - h[i - j]) + ans[i - j]);
        }
    }
    std::cout << ans[n - 1];
}

